3 | /**
4 |  * 工具注册表类
5 |  *
6 |  * 单例模式，管理所有可用的工具
7 |  */
8 | export class ToolRegistry {
9 |     /** 已注册的工具映射 */
10 |     private static tools: Map<string, BaseTool<any>> = new Map();
11 |     private static context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] } = {};
12 | 
13 |     /** 私有构造函数，防止外部实例化 */
14 |     private constructor() {}
15 | 
16 |     /**
17 |      * 注册工具
18 |      *
19 |      * 支持单个工具或工具数组
20 |      *
21 |      * @param tool - 工具实例或工具数组
22 |      * @throws 如果工具名称已存在
23 |      *
24 |      * @example
25 |      * ```ts
26 |      * // 注册单个工具
27 |      * ToolRegistry.register(new BashTool());
28 |      *
29 |      * // 批量注册工具
30 |      * ToolRegistry.register([new BashTool(), new GrepTool()]);
31 |      * ```
32 |      */
33 |     static register<T extends BaseTool<any>>(tool: T | T[]): void {
34 |         const tools = Array.isArray(tool) ? tool : [tool];
35 |         for (const t of tools) {
36 |             if (this.tools.has(t.name)) {
37 |                 throw new Error(`Tool "${t.name}" is already registered`);
38 |             }
39 |             this.tools.set(t.name, t);
40 |         }
41 |     }
42 | 
43 |     /**
44 |      * 注销工具
45 |      *
46 |      * @param name - 工具名称
47 |      * @returns 是否成功注销
48 |      */
49 |     static unregister(name: string): boolean {
50 |         return this.tools.delete(name);
51 |     }
52 | 
53 |     /**
54 |      * 根据名称获取工具
55 |      *
56 |      * @param name - 工具名称
57 |      * @returns 工具实例，如果不存在则返回 undefined
58 |      */
59 |     static get<T extends BaseTool<any> = BaseTool<any>>(name: string): T | undefined {
60 |         return this.tools.get(name) as T | undefined;
61 |     }
62 | 
63 |     /**
64 |      * 获取所有已注册的工具
65 |      *
66 |      * @returns 工具实例数组
67 |      */
68 |     static getAll(): BaseTool<any>[] {
69 |         return Array.from(this.tools.values());
70 |     }
71 | 
72 |     /**
73 |      * 获取所有工具的名称
74 |      *
75 |      * @returns 工具名称数组
76 |      */
77 |     static getNames(): string[] {
78 |         return Array.from(this.tools.keys());
79 |     }
80 | 
81 |     /**
82 |      * 检查工具是否已注册
83 |      *
84 |      * @param name - 工具名称
85 |      * @returns 是否已注册
86 |      */
87 |     static has(name: string): boolean {
88 |         return this.tools.has(name);
89 |     }
90 | 
91 |     /**
92 |      * 获取已注册工具的数量
93 |      *
94 |      * @returns 工具数量
95 |      */
96 |     static get size(): number {
97 |         return this.tools.size;
98 |     }
99 | 
100 |     /**
101 |      * 清空所有已注册的工具
102 |      *
103 |      * @warning 这通常只在测试中使用
104 |      */
105 |     static clear(): void {
106 |         this.tools.clear();
107 |     }
108 | 
109 |     static setContext(context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] }): void {
110 |         const next = { ...this.context, ...context };
111 |         if ('allowedTools' in context && context.allowedTools === undefined) {
112 |             delete (next as any).allowedTools;
113 |         }
114 |         this.context = next;
115 |     }
116 | 
117 |     static getContext(): { sessionId?: string; sessionPath?: string; allowedTools?: string[] } {
118 |         return this.context;
119 |     }
120 | 
121 |     /**
122 |      * 执行指定工具
123 |      *
124 |      * @param name - 工具名称
125 |      * @param args - 工具参数
126 |      * @returns 执行结果
127 |      * @throws 如果工具不存在或参数无效
128 |      */
129 |     static async execute(name: string, args: string): Promise<ToolOutput> {
130 |         const tool = this.get(name);
131 | 
132 |         if (!tool) {
133 |            return `Tool "${name}" not found`;
134 |         }
135 | 
136 |         const allowed = this.context.allowedTools;
137 |         if (allowed && !allowed.includes(name)) {
138 |            return `Tool "${name}" is not allowed in this context`;
139 |         }
140 |         
141 |         
142 |         
143 |        
144 |         const argsObj = JSON.parse(args);
145 |         
146 |         // 验证参数
147 |         const parsed = tool.schema.safeParse(argsObj);
148 |        
